using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class RefineClassIdentity{
 static GameObject go;static Animator rig;static string dir;static Material metal,trim,leather,wood,feather;
 static Material Mat(string name,Color color,float metallic=0){string path=dir+"/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.SetColor("_BaseColor",color);m.SetFloat("_Metallic",metallic);m.SetFloat("_Smoothness",metallic>0?.3f:.15f);m.SetFloat("_Cull",0);EditorUtility.SetDirty(m);return m;}
 static void MeshPart(string name,List<Vector3> v,List<int> t,Material mat,HumanBodyBones bone){var mesh=new Mesh{name=name};mesh.vertices=v.ToArray();mesh.triangles=t.ToArray();mesh.uv=v.Select(p=>new Vector2(p.x*4,p.y*4)).ToArray();mesh.RecalculateNormals();mesh.RecalculateBounds();string path=dir+"/"+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){old.Clear();old.vertices=mesh.vertices;old.triangles=mesh.triangles;old.uv=mesh.uv;old.normals=mesh.normals;old.RecalculateBounds();old.UploadMeshData(false);EditorUtility.SetDirty(old);UnityEngine.Object.DestroyImmediate(mesh);mesh=old;}else AssetDatabase.CreateAsset(mesh,path);var obj=new GameObject("Identity - "+name);obj.transform.SetParent(go.transform,false);obj.AddComponent<MeshFilter>().sharedMesh=mesh;obj.AddComponent<MeshRenderer>().sharedMaterial=mat;obj.transform.SetParent(rig.GetBoneTransform(bone),true);}
 static void Tube(string name,Vector3 a,Vector3 b,float ra,float rb,Material mat,HumanBodyBones bone,int sides=16){var dir=(b-a).normalized;var x=Vector3.Cross(dir,Vector3.forward).normalized;if(x.sqrMagnitude<.1f)x=Vector3.right;var z=Vector3.Cross(dir,x);var vs=new List<Vector3>();var ts=new List<int>();for(int j=0;j<2;j++)for(int i=0;i<sides;i++){float theta=i*2*Mathf.PI/sides;vs.Add((j==0?a:b)+(Mathf.Cos(theta)*x+Mathf.Sin(theta)*z)*(j==0?ra:rb));}for(int i=0;i<sides;i++){int n=(i+1)%sides;ts.AddRange(new[]{i,n,n+sides,i,n+sides,i+sides});}MeshPart(name,vs,ts,mat,bone);}
 static void Ribbon(string name,Vector3[] points,float width,Material mat,HumanBodyBones bone){var vs=new List<Vector3>();var ts=new List<int>();for(int i=0;i<points.Length;i++){var tangent=points[Math.Min(i+1,points.Length-1)]-points[Math.Max(0,i-1)];var side=Vector3.Cross(tangent,Vector3.forward).normalized*width*.5f;vs.Add(points[i]-side);vs.Add(points[i]+side);if(i>0){int k=i*2;ts.AddRange(new[]{k-2,k,k+1,k-2,k+1,k-1});}}MeshPart(name,vs,ts,mat,bone);}
 static void ArcPlate(string name,float y,float radius,float height,float start,float sweep,Material mat,HumanBodyBones bone,Vector3 offset){var vs=new List<Vector3>();var ts=new List<int>();for(int j=0;j<3;j++)for(int i=0;i<=32;i++){float angle=start+sweep*i/32;float r=radius+j*.004f;vs.Add(offset+new Vector3(Mathf.Sin(angle)*r,y-j*height/2,Mathf.Cos(angle)*r*.78f));if(i>0&&j>0){int k=j*33+i;ts.AddRange(new[]{k,k-1,k-34,k,k-34,k-33});}}for(int k=0;k<ts.Count;k+=3){int swap=ts[k];ts[k]=ts[k+2];ts[k+2]=swap;}MeshPart(name,vs,ts,mat,bone);}
 static void Samurai(){foreach(var t in go.GetComponentsInChildren<Transform>().Where(x=>x.name=="Capucha de peregrino"||x.name=="Velo cerrado"||x.name=="Capa de viaje").ToArray())UnityEngine.Object.DestroyImmediate(t.gameObject);var head=rig.GetBoneTransform(HumanBodyBones.Head).position;var vs=new List<Vector3>();var ts=new List<int>();for(int j=0;j<=16;j++)for(int i=0;i<=48;i++){float latitude=j/16f*Mathf.PI*.53f,angle=i/48f*Mathf.PI*2;float rib=1+.018f*Mathf.Cos(angle*12);vs.Add(head+new Vector3(Mathf.Sin(latitude)*Mathf.Cos(angle)*.143f*rib,.055f+Mathf.Cos(latitude)*.185f,Mathf.Sin(latitude)*Mathf.Sin(angle)*.15f*rib-.012f));if(i>0&&j>0){int k=j*49+i;ts.AddRange(new[]{k,k-1,k-50,k,k-50,k-49});}}MeshPart("Kabuto",vs,ts,metal,HumanBodyBones.Head);
 for(int j=0;j<4;j++)ArcPlate("Shikoro "+j,head.y+.055f-j*.038f,.145f+j*.017f,.04f,.6f,Mathf.PI*2-1.2f,metal,HumanBodyBones.Head,new Vector3(head.x,0,head.z-.012f));
 for(int sign=-1;sign<=1;sign+=2){Ribbon("Cresta "+sign,new[]{head+new Vector3(sign*.02f,.17f,.15f),head+new Vector3(sign*.085f,.22f,.17f),head+new Vector3(sign*.14f,.31f,.12f),head+new Vector3(sign*.15f,.36f,.08f)},.035f,trim,HumanBodyBones.Head);}
 ArcPlate("Menpo",head.y+.085f,.117f,.16f,-1.3f,2.6f,metal,HumanBodyBones.Head,new Vector3(head.x,0,head.z+.017f));
 for(int i=0;i<6;i++)ArcPlate("Do lamela "+i,1.40f-i*.046f,.245f-i*.009f,.048f,-1.45f,2.9f,metal,HumanBodyBones.Chest,new Vector3(0,0,.025f));
 foreach(bool left in new[]{true,false}){int sign=left?-1:1;var arm=left?HumanBodyBones.LeftUpperArm:HumanBodyBones.RightUpperArm;var thigh=left?HumanBodyBones.LeftUpperLeg:HumanBodyBones.RightUpperLeg;var shoulder=rig.GetBoneTransform(arm).position;for(int j=0;j<4;j++){float x=shoulder.x+sign*(.04f+j*.037f);Ribbon("Sode "+sign+" "+j,new[]{new Vector3(x,1.50f-j*.02f,-.10f),new Vector3(x,1.52f-j*.02f,.01f),new Vector3(x,1.50f-j*.02f,.13f)},.055f,metal,arm);}for(int j=0;j<5;j++)ArcPlate("Kusazuri "+sign+" "+j,.98f-j*.047f,.12f+j*.003f,.048f,-1.2f,2.4f,metal,thigh,new Vector3(sign*.11f,0,.075f));for(int j=0;j<6;j++)Tube("Lazado "+sign+j,new Vector3(sign*.13f,1.39f-j*.043f,.193f),new Vector3(sign*.13f,1.365f-j*.043f,.195f),.004f,.004f,trim,HumanBodyBones.Chest,6);}
 }
 static void Archer(){var a=new Vector3(.18f,1.02f,-.31f);var b=new Vector3(-.08f,1.59f,-.31f);Tube("Carcaj de cuero",a,b,.06f,.085f,leather,HumanBodyBones.Chest,28);for(int j=0;j<3;j++){var p=Vector3.Lerp(a,b,.05f+j*.44f);Tube("Cincha carcaj "+j,p,p+(b-a).normalized*.027f,.083f,.083f,trim,HumanBodyBones.Chest,24);}for(int i=0;i<8;i++){var end=b+new Vector3(-.08f+(i%4)*.027f,.22f+(i%3)*.025f,(i/4-.5f)*.045f);var begin=end-(b-a).normalized*.48f;Tube("Flecha "+i,begin,end,.0035f,.0035f,wood,HumanBodyBones.Chest,6);Ribbon("Pluma "+i,new[]{end-Vector3.up*.085f,end-Vector3.up*.025f,end},.027f,feather,HumanBodyBones.Chest);}Ribbon("Bandolera del arquero",new[]{new Vector3(-.16f,1.46f,.15f),new Vector3(-.07f,1.32f,.20f),new Vector3(.06f,1.15f,.19f),new Vector3(.17f,1.06f,.15f)},.052f,leather,HumanBodyBones.Chest);}
 static void CapeClearance(){var cape=go.GetComponentsInChildren<MeshFilter>().FirstOrDefault(x=>x.name=="Capa de viaje");if(!cape)return;var source=AssetDatabase.LoadAssetAtPath<Mesh>(dir.Replace("/Identity/","/Outfits/")+"/Capa de viaje.asset")??cape.sharedMesh;var mesh=UnityEngine.Object.Instantiate(source);var v=mesh.vertices;float top=v.Max(p=>p.y),bottom=v.Min(p=>p.y);for(int i=0;i<v.Length;i++){float t=Mathf.InverseLerp(top,bottom,v[i].y);v[i]=new Vector3(v[i].x*.84f,top-t*.40f,-.245f-.06f*t+.014f*Mathf.Cos(v[i].x*50));}mesh.vertices=v;mesh.RecalculateNormals();mesh.RecalculateBounds();string path=dir+"/Manto corto separado.asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){old.Clear();old.vertices=mesh.vertices;old.triangles=mesh.triangles;old.uv=mesh.uv;old.normals=mesh.normals;old.RecalculateBounds();old.UploadMeshData(false);EditorUtility.SetDirty(old);UnityEngine.Object.DestroyImmediate(mesh);mesh=old;}else AssetDatabase.CreateAsset(mesh,path);cape.sharedMesh=mesh;}
 public static string Run(){foreach(string role in new[]{"Warrior","Tank","Archer","Shinobi","Berserker"}){dir="Assets/03_Models/Characters/CindersDetailed/Identity/"+role;System.IO.Directory.CreateDirectory(dir);AssetDatabase.Refresh();string path="Assets/Resources/Presentation/Classes/"+role+".prefab";go=PrefabUtility.LoadPrefabContents(path);try{rig=go.GetComponentInChildren<Animator>();foreach(var t in go.GetComponentsInChildren<Transform>().Where(x=>x.name.StartsWith("Identity - ")).ToArray())UnityEngine.Object.DestroyImmediate(t.gameObject);metal=Mat("Laca negra granate",new Color(.15f,.038f,.03f),.28f);trim=Mat("Laton y cordones",new Color(.35f,.23f,.095f),.5f);leather=Mat("Cuero curtido",new Color(.12f,.065f,.027f));wood=Mat("Madera de fresno",new Color(.35f,.23f,.12f));feather=Mat("Pluma marfil",new Color(.62f,.58f,.46f));CapeClearance();if(role=="Shinobi")Samurai();if(role=="Archer")Archer();PrefabUtility.SaveAsPrefabAsset(go,path);}finally{PrefabUtility.UnloadPrefabContents(go);}}AssetDatabase.SaveAssets();return "Short capes offset behind torso; Archer quiver and arrows; Shinobi kabuto, menpo and lamellar armor";}
}

